"""DocumentTool — create real DOCX files."""
from __future__ import annotations

import io
from typing import Any

from app.tools.base import Tool, ToolResult
from app.tools.office.outline import coerce_sections
from app.tools.office.result_store import ResultStore
from app.tools.office.runner import run_office_job


class DocumentTool(Tool):
    name = "create_document"
    description = (
        "Create a Word (.docx) document with title, headings, and body paragraphs. "
        "Returns a download_url for the generated file."
    )
    input_schema = {
        "type": "object",
        "properties": {
            "title": {"type": "string"},
            "sections": {"type": "array"},
            "outline": {"type": "string"},
            "source_text": {"type": "string"},
            "filename": {"type": "string"},
            "task_id": {"type": "string"},
            "user_id": {"type": "string"},
        },
        "required": [],
    }
    permissions = frozenset({"filesystem:write"})

    def __init__(self, store: ResultStore) -> None:
        self._store = store

    async def execute(self, **kwargs: Any) -> ToolResult:
        title = str(kwargs.get("title") or "").strip() or "Document"
        outline = kwargs.get("outline")
        source_text = kwargs.get("source_text")
        sections_in = kwargs.get("sections")
        filename = str(kwargs.get("filename") or title or "document")

        if not kwargs.get("title") and not outline and not source_text and not sections_in:
            return ToolResult(
                success=False,
                error="Provide title, outline, source_text, or sections to create a document.",
                metadata={"status": "invalid_input"},
            )

        sections = coerce_sections(sections_in or outline, title=title, source_text=source_text)

        async def _build(_tid: str) -> tuple[bytes, str, str, dict[str, Any]]:
            data = _build_docx(title=title, sections=sections)
            return data, filename, "docx", {
                "sections": len(sections),
                "summary": f"Created DOCX «{title}» with {len(sections)} sections.",
            }

        return await run_office_job(
            tool_name=self.name,
            store=self._store,
            build=_build,
            task_id=kwargs.get("task_id") if isinstance(kwargs.get("task_id"), str) else None,
            user_id=kwargs.get("user_id") if isinstance(kwargs.get("user_id"), str) else None,
        )


def _build_docx(*, title: str, sections: list[dict[str, Any]]) -> bytes:
    from docx import Document
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.shared import Pt, RGBColor

    doc = Document()
    heading = doc.add_heading(title, level=0)
    for run in heading.runs:
        run.font.color.rgb = RGBColor(0x1E, 0x1B, 0x4B)

    intro = doc.add_paragraph("Generated by NEXA AI (HEXARI). Editable Word document.")
    intro.alignment = WD_ALIGN_PARAGRAPH.LEFT
    for run in intro.runs:
        run.font.size = Pt(10)
        run.font.color.rgb = RGBColor(0x64, 0x64, 0x74)

    for section in sections:
        doc.add_heading(str(section.get("title") or "Section"), level=1)
        bullets = section.get("bullets") or []
        if not bullets:
            doc.add_paragraph("")
            continue
        for bullet in bullets:
            p = doc.add_paragraph(str(bullet), style="List Bullet")
            for run in p.runs:
                run.font.size = Pt(11)

    buf = io.BytesIO()
    doc.save(buf)
    data = buf.getvalue()
    if len(data) < 500:
        raise ValueError("Generated DOCX appears too small to be valid.")
    return data


def verify_docx_bytes(data: bytes) -> dict[str, Any]:
    from docx import Document

    doc = Document(io.BytesIO(data))
    paras = [p.text for p in doc.paragraphs if p.text.strip()]
    return {"paragraph_count": len(paras), "texts": paras[:20]}
